mapper.select:



		AND menu_name like concat('%', #{menuName}, '%')


		AND hide_in_menu = #{hideInMenu}


		AND status = #{status}


order by parent_id, `order`, id

		select distinct m.id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.route_name, m.hide_in_menu, m.status, ifnull(m.perms,'') as perms, m.link, m.iframe_src, m.keep_alive, m.menu_type, m.icon, m.`order`, m.create_time
		from sys_menu m
		left join sys_role_menu rm on m.id = rm.menu_id
		left join sys_user_role ur on rm.role_id = ur.role_id
		left join sys_role ro on ur.role_id = ro.id
		where ur.user_id = #{params.userId}

            AND m.menu_name like concat('%', #{menuName}, '%')


            AND m.hide_in_menu = #{hideInMenu}


            AND m.status = #{status}

		order by m.parent_id, m.`order`, m.id

select m.id from sys_menu m left join sys_role_menu rm on m.id = rm.menu_id where rm.role_id = #{roleId}
and m.id not in (select m.parent_id from sys_menu m inner join sys_role_menu rm on m.id = rm.menu_id and rm.role_id = #{roleId})
order by m.parent_id, m.`order`, m.id
